    # --- D5: the balance trigger (the constraint that is the design) -----------------------
    # Every entry balances at commit, as a second line of defence behind the validator. It is
    # a DEFERRED constraint trigger so it fires once, at commit, after all of an entry's lines
    # are in place. If it ever fires in production the validator has a bug (logged at ERROR;
    # the student sees the ordinary out-of-balance message).
    op.execute(
        """
        CREATE FUNCTION assert_entry_balanced() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE eid bigint := COALESCE(NEW.entry_id, OLD.entry_id); d bigint; c bigint; n int;
        BEGIN
          SELECT COALESCE(SUM(debit_cents),0), COALESCE(SUM(credit_cents),0), COUNT(*)
            INTO d, c, n FROM entry_line WHERE entry_id = eid;
          IF n > 0 AND (n < 2 OR d <> c) THEN
            RAISE EXCEPTION 'entry % unbalanced (dr %, cr %, lines %)', eid, d, c, n
              USING ERRCODE = 'check_violation';
          END IF;
          RETURN NULL;
        END $$;
        """
    )
    op.execute(
        """
        CREATE CONSTRAINT TRIGGER entry_line_balanced
          AFTER INSERT OR UPDATE OR DELETE ON entry_line
          DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
          EXECUTE FUNCTION assert_entry_balanced();
        """
    )

